/** Building ownership, occupancy, bounded data production and explicitly labelled test-material supply. */
public final class CityHousing {
 public static final class State {public int schema=1;public long clock,day;public boolean started,testSupply,constructionSupplyOnly;public long supplyClock,supplied;public boolean importedMaterials;public long materialImportSegment=-1,materialImportCursor;public Map<String,Long> imported=new TreeMap<>(),exported=new TreeMap<>();public Map<UUID,House> houses=new LinkedHashMap<>();public Map<String,Material> market=new TreeMap<>();public Map<String,Integer> tails=new TreeMap<>();}
 public static final class House {public Set<Long> clears=new HashSet<>(),pendingClear=new HashSet<>();public Map<Long,String> blockData=new HashMap<>();public String stage="BUILT";public boolean extra,artisanWorkshop;public long decayCredit;public long revision,produced;public boolean configured,personal,production;public UUID owner;public int beds,workerLimit;public int periodSeconds=60,quantity=1;public String purpose="";public String product="minecraft:oak_planks",status="尚未记录房屋血量";public Set<UUID> residents=new LinkedHashSet<>(),workers=new LinkedHashSet<>();public Map<UUID,Long> progress=new HashMap<>();@com.google.gson.annotations.JsonAdapter(CityBlockStore.Adapter.class) public Map<Long,String> baseline=new CityBlockStore();public Set<Long> damaged=new HashSet<>();public Map<String,Integer> materials=new TreeMap<>();}
 public static final class Material {public FoodAge.State freshness=new FoodAge.State();public UUID supplier;public int stock,priceCents=40,supply=40,cap=4096;public long supplied,sold;}
 private record Capture(UUID city,UUID building,long revision,int cursor,Map<Long,String> blocks){}
 private static final Map<UUID,Capture> captures=new LinkedHashMap<>();private static int scan;
 private record Points(Object source,long revision,int size,ArrayList<Long> values){}
 private static final Map<House,Points> pointsCache=new WeakHashMap<>();
 private static ArrayList<Long> points(House house){var prior=pointsCache.get(house);long rev=house.baseline instanceof CityBlockStore store?store.revision():0;int size=house.baseline.size();if(prior==null||prior.source!=house.baseline||prior.revision!=rev||prior.size!=size){prior=new Points(house.baseline,rev,size,new ArrayList<>(house.baseline.keySet()));pointsCache.put(house,prior);}return prior.values;}
 static void clear(){captures.clear();pointsCache.clear();scan=0;}
 static void repaired(MinecraftServer server,CityData.City c,BlockPos pos){for(var h:c.housing.houses.values())if(h.baseline.containsKey(pos.asLong()))h.damaged.remove(pos.asLong());CityData.get(server).setDirty();}
 static void changed(ServerLevel level,BlockPos pos,boolean removed){CityWorks.changed(level,pos,removed);var data=CityData.get(level.getServer());for(var c:data.cities())if(!c.works.finalized&&c.dimension.equals(level.dimension().location().toString())&&c.includes(pos))for(var h:c.housing.houses.values())if(h.baseline.containsKey(pos.asLong())){if(removed||!CityMaintenance.same(level.getBlockState(pos),CityMaintenance.decode(h.baseline.get(pos.asLong()))))h.damaged.add(pos.asLong());else h.damaged.remove(pos.asLong());data.setDirty();}}
 static void broken(BlockEvent.BreakEvent e){if(e.isCanceled())return;if(e.getLevel() instanceof ServerLevel l){var c=RuralTools.city(l,e.getPos());if(c!=null&&c.works.pending.containsKey(e.getPos().asLong())){e.setCanceled(true);e.getPlayer().displayClientMessage(Component.literal("正在施工，此处暂时不能改动"),true);return;}CityWorks.beforeTerrainEdit(l,e.getPos(),e.getState());changed(l,e.getPos(),true);}}
 static void placed(BlockEvent.EntityPlaceEvent e){if(e.isCanceled())return;if(e.getLevel() instanceof ServerLevel l){var c=RuralTools.city(l,e.getPos());if(c!=null&&c.works.pending.containsKey(e.getPos().asLong())){e.setCanceled(true);return;}CityWorks.beforeTerrainEdit(l,e.getPos(),e.getBlockSnapshot().getState());changed(l,e.getPos(),false);}}
 static void exploded(ExplosionEvent.Detonate e){if(e.getLevel() instanceof ServerLevel l){e.getAffectedBlocks().removeIf(p->{var c=RuralTools.city(l,p);return c!=null&&c.works.pending.containsKey(p.asLong());});for(var p:e.getAffectedBlocks().stream().limit(8192).toList()){CityWorks.beforeTerrainEdit(l,p,l.getBlockState(p));changed(l,p,true);}}}
 static void interacting(net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock e){if(e.getLevel() instanceof ServerLevel l){var c=RuralTools.city(l,e.getPos());if(c!=null&&(c.works.pending.containsKey(e.getPos().asLong())||c.works.deferredContainers.contains(e.getPos().asLong()))){e.setCanceled(true);e.setCancellationResult(net.minecraft.world.InteractionResult.FAIL);}}}
 static boolean pending(ServerLevel l,BlockPos p){var c=RuralTools.city(l,p);return c!=null&&c.works.pending.containsKey(p.asLong());}
 static void piston(net.neoforged.neoforge.event.level.PistonEvent.Pre event){if(!(event.getLevel() instanceof ServerLevel l)||event.isCanceled())return;var resolver=event.getStructureHelper();if(resolver==null)return;resolver.resolve();var positions=new HashSet<BlockPos>(resolver.getToPush());positions.addAll(resolver.getToDestroy());positions.add(event.getPos());positions.add(event.getFaceOffsetPos());var shift=event.getPistonMoveType().isExtend?event.getDirection():event.getDirection().getOpposite();for(var p:new ArrayList<>(positions))positions.add(p.relative(shift));if(positions.stream().anyMatch(p->pending(l,p)))event.setCanceled(true);}
 static House defaults(CityRegistry.Building b){var h=new House();h.purpose=b.type();h.personal=b.type().equals("住宅")||b.type().equals("工坊");h.beds=b.type().equals("住宅")?3:0;h.workerLimit=b.type().equals("工坊")?2:0;return h;}
 static House house(CityData.City c,UUID building){var b=c.buildings.get(building);CityEconomy.require(b!=null,"房屋登记不存在");return c.housing.houses.computeIfAbsent(building,k->defaults(b));}
 static void seedCatalog(State state){for(String id:List.of("minecraft:oak_planks","minecraft:glass","minecraft:stone_bricks","minecraft:cobblestone","minecraft:stone","minecraft:dirt","minecraft:grass_block","minecraft:sand","minecraft:gravel"))state.market.computeIfAbsent(id,k->{var m=new Material();m.priceCents=List.of("minecraft:dirt","minecraft:grass_block","minecraft:stone","minecraft:cobblestone","minecraft:sand","minecraft:gravel").contains(id)?1:id.equals("minecraft:oak_planks")?20:id.equals("minecraft:glass")?30:40;return m;});}
 static void validate(CityData.City c,State state){CityEconomy.require(state!=null&&state.imported!=null&&state.exported!=null&&state.imported.size()<=128&&state.exported.size()<=128&&state.materialImportCursor>=0,"建材进口账容量无效");for(var ledger:List.of(state.imported,state.exported))ledger.forEach((item,n)->{CityEconomy.item(item);CityEconomy.require(n>=0,"建材进口账不能为负");});CityEconomy.require(state!=null&&state.schema==1&&state.houses.size()<=128&&state.market.size()<=128&&state.tails.size()<=8192,"房屋数据容量或版本错误");var occupants=new HashSet<UUID>();var workers=new HashSet<UUID>();
  CityEconomy.require(state.houses.values().stream().mapToInt(v->v.workers.size()).sum()<=512,"房屋工人数超过512");
  for(var entry:state.houses.entrySet()){var b=c.buildings.get(entry.getKey());CityEconomy.require(b!=null,"房屋属性引用了不存在的建筑");var h=entry.getValue();validateHouse(h);for(UUID resident:h.residents)CityEconomy.require(occupants.add(resident),"住户重复");for(UUID id:h.workers)CityEconomy.require(workers.add(id),"工人重复归属");CityEconomy.require(h.baseline.keySet().containsAll(h.damaged),"损坏坐标不在房屋基准中");CityEconomy.require(CityBlockStore.inside(h.baseline,b.bounds()),"房屋血量坐标越界");for(String value:CityBlockStore.states(h.baseline))CityMaintenance.decode(value);}
  for(var entry:state.market.entrySet()){CityEconomy.item(entry.getKey());var m=entry.getValue();CityEconomy.require(m.stock>=0&&m.stock<=4096&&m.priceCents>=1&&m.priceCents<=1000000&&m.supply>=0&&m.supply<=4096&&m.cap>=1&&m.cap<=4096,"建材库存/报价/测试供货无效");}state.tails.values().forEach(v->CityEconomy.require(v>=0&&v<100,"材料货款尾数无效"));
 }
 static void validateHouse(House h){CityEconomy.require(h!=null&&h.revision>=0&&h.beds>=0&&h.beds<=1000&&h.workerLimit>=0&&h.workerLimit<=512&&h.residents.size()<=h.beds&&h.workers.size()<=h.workerLimit&&h.periodSeconds>=1&&h.periodSeconds<=86400&&h.quantity>=1&&h.quantity<=4096&&h.baseline.size()<=131072,"容量、生产参数或人数越界");CityEconomy.item(h.product);CityEconomy.require(h.materials.size()<=128&&h.materials.values().stream().allMatch(n->n>=0&&n<=4096),"房屋材料库存越界");h.materials.keySet().forEach(CityEconomy::item);}
 static String payer(CityData.City c,House h){CityEconomy.require(!h.personal||h.owner!=null,"私人房屋尚未指定所有者，不能支出");return h.personal?CityEconomy.person(h.owner):CityEconomy.treasury(c.id);}
 static String tailKey(MinecraftServer s,CityData.City c,String payer,String item){var vendor=CityModel.materialVendor(s,c,item);return vendor==null?payer:payer+"|"+vendor.account;}
 static long purchase(CityData.City c,House h,String item,int quantity,CityEconomy economy){CityEconomy.require(quantity>0&&quantity<=4096,"采购数量1—4096");var m=c.housing.market.get(item);CityEconomy.require(m!=null&&m.stock>=quantity,"市场材料不足");String from=payer(c,h),seller=CityModel.materialAccount(economy.serverContext,c,item),tailKey=tailKey(economy.serverContext,c,from,item);CityEconomy.require(economy.balance(from)>0,"付款账户无资金");int old=h.materials.getOrDefault(item,0);CityEconomy.require(old+quantity<=4096&&(h.materials.containsKey(item)||h.materials.size()<128),"房屋材料库已满");long cents=(long)m.priceCents*quantity+c.housing.tails.getOrDefault(tailKey,0),paid=cents/100;CityEconomy.require(economy.balance(from)>=paid,"付款账户余额不足");CityEconomy.require(economy.balance(seller)+paid<=CityEconomy.LIMIT,"市场账户余额超限");m.stock-=quantity;m.sold+=quantity;h.materials.put(item,old+quantity);c.housing.tails.put(tailKey,(int)(cents%100));economy.state.accounts.put(from,economy.balance(from)-paid);economy.state.accounts.put(seller,economy.balance(seller)+paid);CityModel.materialSold(economy.serverContext,c,item,quantity,paid);economy.log(c.housing.clock,"BUILD_MATERIAL",from,seller,paid,"房屋采购 "+item+" x"+quantity);economy.setDirty();return paid;}
 static boolean repairMaterial(MinecraftServer s,CityData.City c,BlockPos pos,net.minecraft.world.level.block.state.BlockState target){var b=c.buildings.values().stream().filter(v->v.bounds().contains(pos)&&c.housing.houses.containsKey(v.id())&&c.housing.houses.get(v.id()).configured).findFirst().orElse(null);if(b==null)return true;var h=house(c,b.id());String id=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(target.getBlock().asItem()).toString();if(id.equals("minecraft:air")){h.status="无法确定该方块的修复材料";return false;}try{if(h.materials.getOrDefault(id,0)==0)purchase(c,h,id,1,CityEconomy.get(s));h.materials.compute(id,(k,n)->n-1);CityData.get(s).setDirty();return true;}catch(IllegalArgumentException e){h.status="修补等待："+e.getMessage();return false;}}
 static void refundMaterial(CityData.City c,BlockPos pos,net.minecraft.world.level.block.state.BlockState target){for(var b:c.buildings.values())if(b.bounds().contains(pos)){var h=c.housing.houses.get(b.id());if(h!=null&&h.configured){String id=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(target.getBlock().asItem()).toString();h.materials.merge(id,1,Integer::sum);}break;}}
 static House view(House h){var v=new House();v.stage=h.stage;v.extra=h.extra;v.artisanWorkshop=h.artisanWorkshop;v.purpose=h.purpose;v.configured=h.configured;v.revision=h.revision;v.personal=h.personal;v.owner=h.owner;v.beds=h.beds;v.workerLimit=h.workerLimit;v.periodSeconds=h.periodSeconds;v.quantity=h.quantity;v.product=h.product;v.production=h.production;v.produced=h.produced;v.status=h.status;v.residents=h.residents;v.workers=h.workers;v.materials=h.materials;return v;}
 static void capacity(CityData.City c,UUID building,UUID worker,CityEconomy economy){var h=c.housing.houses.get(building);if(h==null||!h.configured)return;var staff=new HashSet<>(h.workers);for(var j:economy.state.production)if(j.enabled&&j.city.equals(c.id)&&j.building.equals(building))staff.add(j.worker);staff.add(worker);CityEconomy.require(staff.size()<=h.workerLimit,"房屋工人容量不足");}
 static void assign(CityData.City c,UUID building,UUID npc,int mode,CityEconomy economy){var h=house(c,building);CityEconomy.require(c.residents.contains(npc),"只能选择本城居民");CityEconomy.require(mode>=0&&mode<=2,"未知居民关联类型");var set=mode==1?h.residents:h.workers;if(mode==0){h.owner=npc;return;}CityEconomy.require(h.stage.equals("BUILT"),"建筑尚未竣工，不能安排住户或工作岗位");if(set.remove(npc)){if(mode==2)h.progress.remove(npc);return;}CityEconomy.require(set.size()<(mode==1?h.beds:h.workerLimit),"房屋容量已满");for(var entry:c.housing.houses.entrySet())if(!entry.getKey().equals(building))CityEconomy.require(!(mode==1?entry.getValue().residents:entry.getValue().workers).contains(npc),"该居民已有住房/工作房屋，请先解除");if(mode==2){CityEconomy.require(c.housing.houses.values().stream().mapToInt(v->v.workers.size()).sum()<512,"本城房屋工人总数已达512");CityEconomy.require(economy.state.production.stream().noneMatch(j->j.enabled&&j.worker.equals(npc)),"该居民已有生产任务");var rural=RuralSettlement.get(economy.serverContext).state;CityEconomy.require(rural.sites.values().stream().noneMatch(site->site.present&&npc.equals(site.worker)),"该居民已有农村工作点");}set.add(npc);}
 static void capture(MinecraftServer s,CityData.City c,UUID id){var b=c.buildings.get(id);var l=CityEconomy.level(s,c);for(int x=b.bounds().min().getX()>>4;x<=b.bounds().max().getX()>>4;x++)for(int z=b.bounds().min().getZ()>>4;z<=b.bounds().max().getZ()>>4;z++)CityEconomy.require(l.hasChunk(x,z),"请先靠近房屋，记录不会强制加载区块");CityEconomy.require(!captures.containsKey(c.id),"本城正在记录另一栋房屋");var h=house(c,id);CityEconomy.require(h.configured&&(!h.personal||h.owner!=null),"请先指定产权与所有者并保存房屋属性");captures.put(c.id,new Capture(c.id,id,h.revision,0,new CityBlockStore()));h.status="正在分批记录房屋血量";}
 static void advanceSupply(State state,int ticks){if(!state.testSupply)return;state.supplyClock+=ticks;while(state.supplyClock>=1200){state.supplyClock-=1200;for(var entry:state.market.entrySet()){if(state.constructionSupplyOnly&&!CityMaterialCatalog.material(entry.getKey()))continue;if(state.importedMaterials&&CityMaterialCatalog.material(entry.getKey()))continue;var m=entry.getValue();int n=Math.max(0,Math.min(m.supply,m.cap-m.stock));m.stock+=n;m.supplied+=n;state.supplied+=n;}}}
 static int efficiency(House h){return CityWorks.efficiency(h);}
 static void work(House h,UUID worker,State market,int ticks){long progress=h.progress.getOrDefault(worker,0L)+(long)ticks*efficiency(h),period=h.periodSeconds*20L*10000;if(progress>=period){var m=market.market.get(h.product);if(m==null&&market.market.size()>=128){h.status="市场商品种类已满";h.progress.put(worker,period);return;}m=market.market.computeIfAbsent(h.product,k->new Material());if(m.stock+h.quantity<=4096){m.stock+=h.quantity;h.produced+=h.quantity;progress-=period;h.status="简化生产已入市场；原料链待补充";}else{progress=period;h.status="市场满仓，产出保留为待生产";}}h.progress.put(worker,progress);}
 static void tick(MinecraftServer s){var data=CityData.get(s);if(!captures.isEmpty()){var task=captures.values().iterator().next();var c=data.cities.get(task.city);var b=c==null?null:c.buildings.get(task.building);if(b==null){captures.remove(task.city);}else{var h=house(c,b.id());if(h.revision!=task.revision){h.status="设置变化，记录取消";captures.remove(c.id);}else{var l=CityEconomy.level(s,c);int cursor=task.cursor;for(int n=0;n<512&&cursor<b.bounds().volume();n++){var pos=b.bounds().at(cursor);if(!l.hasChunkAt(pos))break;cursor++;var state=l.getBlockState(pos);if(!state.isAir()&&!(state.getBlock() instanceof net.minecraft.world.level.block.LiquidBlock)&&!(state.getBlock() instanceof CropBlock))task.blocks.put(pos.asLong(),CityMaintenance.encode(state));}if(cursor==b.bounds().volume()){{try{CityMaintenance.recordHouse(s,c,b,task.blocks);h.baseline=task.blocks;if(h.baseline instanceof CityBlockStore store)store.compact();h.damaged.clear();h.status="房屋基准已记录："+h.baseline.size()+"血";h.revision++;}catch(IllegalArgumentException ex){h.status="记录拒绝，旧基准保留："+ex.getMessage();}}captures.remove(c.id);}else captures.put(c.id,new Capture(c.id,b.id(),task.revision,cursor,task.blocks));data.setDirty();}}}
  int steps=SimulationClock.steps(s);if(steps==0)return;var economy=CityEconomy.get(s);for(var c:data.cities()){if(CityCurrency.model(s,c.id)&&!RuralSettlement.active(s,c.id))continue;var st=c.housing;if(st.houses.isEmpty()&&!st.testSupply)continue;if(!st.started){st.day=s.overworld().getDayTime();st.started=true;}var ruralClock=RuralSettlement.get(s).state;if(ruralClock.clockStarted&&!ruralClock.enabled.isEmpty())st.day=ruralClock.simulationDay;if(s.getTickCount()%20==0)for(var home:st.houses.values()){java.util.function.Predicate<UUID> departed=id->{if(!c.residents.contains(id))return true;var rural=RuralSettlement.get(s).state.people.get(id);if(rural!=null)return rural.dead;var entity=CityEconomy.level(s,c).getEntity(id);return entity!=null&&!entity.isAlive();};home.residents.removeIf(departed);home.workers.removeIf(departed);home.progress.keySet().retainAll(home.workers);}for(int n=0;n<steps;n++){st.clock+=20;st.day+=20;advanceSupply(st,20);for(var entry:st.houses.entrySet()){var h=entry.getValue();if(!h.production)continue;if(efficiency(h)==0){h.status="等待记录房屋或恢复血量";continue;}for(UUID worker:h.workers){var person=RuralSettlement.get(s).state.people.get(worker);if(person!=null&&person.dead)continue;if(person==null&&!CityMaintenance.available(CityEconomy.level(s,c),c,worker))continue;var hours=WorkHours.config(s,worker);if(!WorkHours.allowed(hours,st.day,CityLiving.stability(economy,c),Math.floorMod(Objects.hash(worker,Math.floorDiv(st.day-12000,24000)),100)))continue;work(h,worker,st,20);}}}data.setDirty();}
  var homes=new ArrayList<Map.Entry<CityData.City,House>>();for(var c:data.cities())for(var h:c.housing.houses.values())if(!h.baseline.isEmpty())homes.add(Map.entry(c,h));if(!homes.isEmpty()){var pair=homes.get(Math.floorMod(scan++,homes.size()));var c=pair.getKey();var h=pair.getValue();var positions=points(h);int start=Math.floorMod(scan/homes.size()*128,positions.size());var l=CityEconomy.level(s,c);for(int i=0;i<Math.min(128,positions.size());i++){long p=positions.get((start+i)%positions.size());var pos=BlockPos.of(p);if(l.hasChunkAt(pos)&&!c.works.finalized){var maintenance=CityMaintenance.get(s).state.cities.get(c.id);if((maintenance!=null&&maintenance.ready.contains(p))||CityMaintenance.same(l.getBlockState(pos),CityMaintenance.decode(h.baseline.get(p))))h.damaged.remove(p);else h.damaged.add(p);}}}
 }
 static void request(ServerPlayer p,CityNetwork.Request r){try{var c=CityData.get(p.server).require(UUID.fromString(r.city()));CityEconomy.require(CityService.editor(p),"需要管理员或城市所有者权限");CityEconomy.require(c.dimension.equals(p.level().dimension().location().toString()),"城市维度不一致");UUID id=UUID.fromString(r.value().split("\n",2)[0]);var h=house(c,id);String message="";var economy=CityEconomy.get(p.server);if(!r.op().equals("houseview"))CityEconomy.require(r.revision()==h.revision,"房屋设置已更新，请刷新");
   switch(r.op()){case "houseview"->{}case "housesave"->{var inputJson=JsonParser.parseString(r.value().split("\n",2)[1]);CityMaintenance.exact(inputJson);var input=CityEconomy.JSON.fromJson(inputJson,House.class);validateHouse(input);CityEconomy.require(h.residents.size()<=input.beds&&h.workers.size()<=input.workerLimit,"请先解除超出新容量的住户/工人");CityEconomy.require(!input.personal||h.owner!=null,"先选择私人所有者");CityEconomy.require(!input.production||economy.state.production.stream().noneMatch(j->j.enabled&&j.city.equals(c.id)&&j.building.equals(id)),"本屋已有旧生产任务，先停用以免重复生产");int legacy=(int)economy.state.production.stream().filter(j->j.enabled&&j.city.equals(c.id)&&j.building.equals(id)).map(j->j.worker).distinct().count();CityEconomy.require(legacy<=input.workerLimit,"容量低于现有生产工人数");if(!h.product.equals(input.product)||h.periodSeconds!=input.periodSeconds||h.quantity!=input.quantity)h.progress.clear();if(!input.purpose.isEmpty()){CityEconomy.require(CityRegistry.TYPES.contains(input.purpose),"未知房屋用途");var old=c.buildings.get(id);c.buildings.put(id,new CityRegistry.Building(id,old.name(),input.purpose,old.bounds()));h.purpose=input.purpose;CityData.get(p.server).changed(c);}h.configured=true;h.personal=input.personal;h.beds=input.beds;h.workerLimit=input.workerLimit;h.periodSeconds=input.periodSeconds;h.quantity=input.quantity;h.product=input.product;h.production=input.production;h.revision++;CityMaintenance.enableDataCity(p.server,c);message="房屋属性已保存";}case "housecapture"->{capture(p.server,c,id);message="开始记录房屋方块；不包含箱内物品";}case "houseperson"->{assign(c,id,UUID.fromString(r.value().split("\n",2)[1]),r.x(),economy);h.revision++;CityMaintenance.enableDataCity(p.server,c);message="居民关联已保存";}case "housesupply"->{seedCatalog(c.housing);c.housing.testSupply=r.surface();message="测试虚空供货"+(r.surface()?"已开启":"已关闭");}case "housemat"->{String[] a=r.value().split("\n");CityEconomy.item(a[1]);CityEconomy.require(c.housing.market.size()<128||c.housing.market.containsKey(a[1]),"商品种类已满");CityEconomy.require(r.x()>=1&&r.x()<=1000000&&r.y()>=0&&r.y()<=4096,"报价/供货数量越界");var m=c.housing.market.computeIfAbsent(a[1],k->new Material());m.priceCents=r.x();m.supply=r.y();message="建材报价与测试供货量已保存";}case "housebuy"->{long paid=purchase(c,h,r.value().split("\n",2)[1],r.x(),economy);message="已采购入房屋材料库，支付"+paid+"银币，零头累计结算";}default->throw new IllegalArgumentException("未知房屋操作");}CityData.get(p.server).setDirty();snapshot(p,c,id,r.z(),message);
  }catch(Exception e){try{var c=CityData.get(p.server).require(UUID.fromString(r.city()));if(CityService.editor(p)){snapshot(p,c,UUID.fromString(r.value().split("\\n",2)[0]),r.z(),"拒绝："+e.getMessage());return;}}catch(Exception ignored){}p.sendSystemMessage(Component.literal("[房屋] "+e.getMessage()));}}
 static void snapshot(ServerPlayer p,CityData.City c,UUID id,int tab,String message){var h=house(c,id);seedCatalog(c.housing);var t=new CompoundTag();t.putBoolean("Housing",true);t.putString("Id",c.id.toString());t.putString("Name",c.name);t.putString("HouseId",id.toString());t.putString("HouseName",c.buildings.get(id).name());t.putString("Type",c.buildings.get(id).type());t.putString("House",CityEconomy.JSON.toJson(view(h)));t.putLong("Revision",c.revision);t.putLong("HouseRevision",h.revision);t.putLong("CityRevision",c.revision);t.putInt("Efficiency",CityWorks.efficiency(h));t.putInt("Health",h.baseline.size()-h.damaged.size());t.putInt("MaxHealth",h.baseline.size());t.putInt("Tab",tab);t.putBoolean("Editable",true);t.putBoolean("TestSupply",c.housing.testSupply);t.putString("Market",CityEconomy.JSON.toJson(c.housing.market));t.putString("Message",message);try{String payer=payer(c,h);t.putString("Payer",payer);t.putLong("Balance",CityEconomy.get(p.server).balance(payer));}catch(Exception e){t.putString("Payer","私人所有者待指定");}CityRegistry.snapshot(p,c,t);ListTag people=new ListTag();for(UUID npc:c.residents.stream().sorted().toList()){var n=new CompoundTag();n.putString("Id",npc.toString());var rural=RuralSettlement.get(p.server).state.people.get(npc);var entity=p.serverLevel().getEntity(npc);n.putString("Name",rural!=null?rural.name:entity==null?"居民 "+npc.toString().substring(0,8):entity.getName().getString());n.putBoolean("Dead",rural!=null&&rural.dead);people.add(n);}t.put("People",people);PacketDistributor.sendToPlayer(p,new CityNetwork.Snapshot(t));}
}

